#' Build package vignettes from \code{vignettes/sources/*.Rmd}
#'
#' Pre-knits each editable source under \code{vignettes/sources/} to a static
#' \code{vignettes/<name>.Rmd} (figures under \code{vignettes/figures/<name>/})
#' so \code{R CMD check} / CRAN do not re-run Stan-heavy chunks.
#'
#' Edit files in \code{vignettes/sources/} only, then call this helper.
#' Do not edit the frozen \code{vignettes/*.Rmd} by hand. See
#' \code{vignettes/README.md} and \code{CONTRIBUTING.md}.
#'
#' @param vignettes Character vector of vignette basenames (no extension).
#'   Default: all maintained vignettes. Use \code{only} to rebuild a subset.
#' @param only Optional character vector; if set, only these basenames are
#'   built (overrides \code{vignettes}).
#' @param package_dir Path to the CausalQueries package root (directory that
#'   contains \code{DESCRIPTION} and \code{vignettes/}). Default: search from
#'   the working directory upward, then \code{CausalQueries} under the
#'   parent of \code{getwd()} (monorepo layout).
#' @return Invisibly, the character vector of basenames that were built.
#' @keywords internal
#' @noRd
build_vignettes <- function(vignettes = c(
                              "a-getting-started",
                              "b-plotting",
                              "c-canonical-models",
                              "d-front-door",
                              "e-posteriors",
                              "f-complier-profiling",
                              "g-factorized-path"
                            ),
                            only = NULL,
                            package_dir = NULL) {
  if (!is.null(only)) {
    vignettes <- only
  }
  vignettes <- unique(as.character(vignettes))
  if (!length(vignettes)) {
    stop("No vignettes specified.", call. = FALSE)
  }

  package_dir <- find_vignette_package_dir(package_dir)
  vig_dir <- file.path(package_dir, "vignettes")
  src_dir <- file.path(vig_dir, "sources")
  if (!dir.exists(vig_dir)) {
    stop("No vignettes/ directory under ", package_dir, call. = FALSE)
  }
  if (!dir.exists(src_dir)) {
    stop("No vignettes/sources/ directory under ", package_dir, call. = FALSE)
  }

  old_wd <- getwd()
  on.exit(setwd(old_wd), add = TRUE)
  setwd(vig_dir)

  for (v in vignettes) {
    src <- file.path("sources", paste0(v, ".Rmd"))
    out_rmd <- paste0(v, ".Rmd")
    fig_dir <- file.path("figures", v)
    if (!file.exists(src)) {
      stop("Missing vignette source: ", file.path(vig_dir, src), call. = FALSE)
    }
    dir.create(fig_dir, recursive = TRUE, showWarnings = FALSE)

    message("Knitting ", src, " -> ", out_rmd)
    knitr::knit(src, output = out_rmd, quiet = FALSE)

    # Banner so the frozen file is obviously not the edit target
    banner <- paste0(
      "<!-- Generated by CausalQueries:::build_vignettes(); ",
      "edit sources/", v, ".Rmd instead. Do not edit this file. -->\n\n"
    )
    out_txt <- readLines(out_rmd, warn = FALSE)
    # Insert after YAML front matter if present
    if (length(out_txt) >= 1L && identical(out_txt[[1]], "---")) {
      end_yaml <- which(out_txt == "---")
      end_yaml <- end_yaml[end_yaml > 1L][1]
      if (!is.na(end_yaml)) {
        out_txt <- c(out_txt[seq_len(end_yaml)], "", banner, out_txt[-seq_len(end_yaml)])
      } else {
        out_txt <- c(banner, out_txt)
      }
    } else {
      out_txt <- c(banner, out_txt)
    }
    writeLines(out_txt, out_rmd)
  }

  invisible(vignettes)
}

#' Locate package root for vignette builds.
#' @keywords internal
#' @noRd
find_vignette_package_dir <- function(package_dir = NULL) {
  if (!is.null(package_dir)) {
    package_dir <- normalizePath(package_dir, winslash = "/", mustWork = TRUE)
    if (!file.exists(file.path(package_dir, "DESCRIPTION"))) {
      stop("`package_dir` has no DESCRIPTION: ", package_dir, call. = FALSE)
    }
    return(package_dir)
  }

  # Walk up from getwd() looking for DESCRIPTION + vignettes/
  cur <- normalizePath(getwd(), winslash = "/", mustWork = TRUE)
  for (i in 1:8) {
    if (file.exists(file.path(cur, "DESCRIPTION")) &&
        dir.exists(file.path(cur, "vignettes"))) {
      return(cur)
    }
    parent <- dirname(cur)
    if (identical(parent, cur)) {
      break
    }
    cur <- parent
  }

  # Monorepo: .../CQ/CausalQueries when cwd is .../CQ or a sibling
  candidate <- file.path(dirname(normalizePath(getwd(), winslash = "/", mustWork = TRUE)),
                         "CausalQueries")
  if (file.exists(file.path(candidate, "DESCRIPTION")) &&
      dir.exists(file.path(candidate, "vignettes"))) {
    return(normalizePath(candidate, winslash = "/", mustWork = TRUE))
  }

  stop(
    "Could not find CausalQueries package root. Pass package_dir=.",
    call. = FALSE
  )
}
